const clas = $('HTTP — Anticipation annulation (RF)').first().json;
const seg = $('HTTP — Segment fidélité client').first().json;
const statut = clas.statut_predit || 'inconnu';
return [{
  json: {
    timestamp: new Date().toISOString(),
    workflow_label: 'CRM Pipeline',
    utilisateur: 'Anas Allam',
    classification: {
      statut_predit: statut,
      probabilites: clas.probabilites,
      modele: clas.modele,
      alerte: statut === 'cancelled' ? 'ALERTE : risque annulation élevé' : 'RAS',
    },
    segmentation: {
      segment_id: seg.segment_id,
      segment_label: seg.segment_label,
      modele: seg.modele,
    },
    action_recommandee: statut === 'cancelled'
      ? 'Contacter le client en priorité'
      : 'Suivi standard',
  },
}];

const p = $('Code — Analyse CRM + action').first().json;
const probs = p.classification?.probabilites || {};
const cancelled = parseFloat(probs.cancelled ?? probs.Cancelled ?? 0) || 0;
return [{
  json: {
    experiment_name: 'n8n_CRM_Pipeline',
    run_name: 'crm_n8n_' + new Date().toISOString().replace(/[:.]/g, '-'),
    params: {
      workflow: 'crm',
      user: 'anas_allam',
      model_classification: String(p.classification?.modele || ''),
      model_segmentation: String(p.segmentation?.modele || ''),
    },
    metrics: {
      segment_id: parseFloat(p.segmentation?.segment_id) || 0,
      prob_cancelled: cancelled,
    },
    tags: { source: 'n8n', pipeline: 'crm', automated: 'true' },
    artifacts: { summary: p },
  },
}];
